 
--check for Live Casino
-- run on database casino
SELECT * 
FROM CustInfo WITH (nolock)
WHERE Custid not in (select lvcustsettingid from lvcustsetting with (nolock))
and SyncLiveCasino=1
and currency<>20
and enabled=1
order by roleid


