=======================================================
--check Casino
-- run on DBTRANS
SELECT c.creatdate,c.username, co.roleid 
FROM CustInfo co WITH (nolock)
	inner join customer c with (nolock) on co.custid=c.custid
WHERE co.Custid not in (SELECT isnull(IBCCustid,0) FROM DBCasino.CasinoAdmin.dbo.Customer WITH (nolock))
and SyncCasino=1
and co.currency<>20
and enabled=1
and co.srecommend not in (select custid from f_DepSuper_1('All'))
order by co.roleid,c.creatdate

UPDATE custinfo WITH(ROWLOCK)
SET syncCasino = 0
WHERE custid IN (6597932	,
